# Music Player UI - Code Review Package

## Project Overview
A modern mobile music player screen UI with liquid glass aesthetic for a contemporary streaming app. Features frosted glass cards with glassmorphism effects, smooth animations, and a calming white-to-blue gradient background.

## Design Specifications
- **Resolution**: 1080×2400px (mobile portrait)
- **Design Style**: Liquid glass aesthetic with glassmorphism
- **Color Palette**: White to blue gradient (#FFFFFF → #E9F7FF → #D0ECFF)
- **Primary Accent**: #2F80ED (blue) → #0AA1FF (bright blue)
- **Effects**: 18-26px blur, semi-transparent borders, layered shadows
- **Typography**: Inter/SF Pro with proper hierarchy
- **Layout Grid**: 4px baseline with 16-24px padding

## Tech Stack
- React 18+ with TypeScript
- Tailwind CSS v4.0
- Motion (Framer Motion) for animations
- Lucide React for icons
- Unsplash for placeholder images

---

## File Structure

```
/App.tsx                          # Main app component with view switching
/components/MusicPlayer.tsx       # Full-screen player component
/components/MiniPlayer.tsx        # Compact mini-player bar
/components/ColorSwatches.tsx     # Color palette reference panel
/styles/globals.css               # Global styles and design tokens
```

---

## Code Files

### 1. App.tsx
**Purpose**: Main entry point with animated view switching between full player, mini player, and control closeup.

\`\`\`tsx
import { useState } from 'react';
import { MusicPlayer } from './components/MusicPlayer';
import { MiniPlayer } from './components/MiniPlayer';
import { ColorSwatches } from './components/ColorSwatches';
import { motion } from 'motion/react';

export default function App() {
  const [view, setView] = useState<'full' | 'mini' | 'controls'>('full');

  return (
    <div className="min-h-screen bg-gradient-to-b from-white via-[#E9F7FF] to-[#D0ECFF] flex items-center justify-center p-4">
      <div className="w-full max-w-[420px] relative">
        {/* View Toggle */}
        <motion.div 
          className="absolute top-4 right-4 z-50 flex gap-2 p-1.5 rounded-full backdrop-blur-xl"
          style={{
            background: 'rgba(255,255,255,0.5)',
            border: '1.5px solid rgba(255,255,255,0.3)',
            boxShadow: '0 8px 24px rgba(47,128,237,0.15), inset 0 1px 0 rgba(255,255,255,0.6)',
          }}
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
        >
          {(['full', 'mini', 'controls'] as const).map((option) => (
            <motion.button
              key={option}
              onClick={() => setView(option)}
              className={\`px-3 py-1.5 rounded-full text-sm transition-colors relative \${
                view === option
                  ? 'text-white'
                  : 'text-gray-700'
              }\`}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              transition={{ type: "spring", stiffness: 400, damping: 17 }}
            >
              {view === option && (
                <motion.div
                  className="absolute inset-0 bg-gradient-to-br from-[#2F80ED] to-[#0AA1FF] rounded-full"
                  layoutId="activeView"
                  transition={{ type: "spring", stiffness: 400, damping: 30 }}
                  style={{
                    boxShadow: '0 2px 8px rgba(47,128,237,0.4)',
                  }}
                />
              )}
              <span className="relative z-10 capitalize">
                {option}
              </span>
            </motion.button>
          ))}
        </motion.div>

        {/* Main Content */}
        {view === 'full' && <MusicPlayer />}
        {view === 'mini' && (
          <div className="h-[800px] flex items-end">
            <MiniPlayer />
          </div>
        )}
        {view === 'controls' && <MusicPlayer showControlsCloseup />}

        {/* Color Swatches Overlay */}
        <ColorSwatches />
      </div>
    </div>
  );
}
\`\`\`

---

### 2. MusicPlayer.tsx
**Purpose**: Main full-screen music player with glassmorphism cards, animated waveform, controls, and two view modes (full player and control closeup).

\`\`\`tsx
import { useState } from 'react';
import { Search, Play, Pause, SkipBack, SkipForward, Shuffle, Repeat, Heart, Download, List, MessageSquare } from 'lucide-react';
import { ImageWithFallback } from './figma/ImageWithFallback';
import { motion, AnimatePresence } from 'motion/react';

interface MusicPlayerProps {
  showControlsCloseup?: boolean;
}

export function MusicPlayer({ showControlsCloseup = false }: MusicPlayerProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(45);
  const [isLiked, setIsLiked] = useState(false);
  const [isShuffle, setIsShuffle] = useState(false);
  const [repeatMode, setRepeatMode] = useState<'off' | 'all' | 'one'>('off');

  if (showControlsCloseup) {
    return (
      <div className="h-[800px] flex items-center justify-center p-8">
        <div className="relative">
          {/* Close-up of Play Control with Glass Effect */}
          <div className="relative">
            {/* Outer glow layers */}
            <motion.div 
              className="absolute inset-0 bg-[#2F80ED]/30 blur-[80px] scale-150 rounded-full"
              animate={{
                scale: isPlaying ? [1.5, 1.6, 1.5] : 1.5,
                opacity: isPlaying ? [0.3, 0.4, 0.3] : 0.3,
              }}
              transition={{
                duration: 2,
                repeat: Infinity,
                ease: "easeInOut"
              }}
            />
            <div className="absolute inset-0 bg-[#0AA1FF]/20 blur-[60px] scale-125 rounded-full" />

            {/* Main control button */}
            <motion.button
              onClick={() => setIsPlaying(!isPlaying)}
              className="relative w-32 h-32 rounded-full bg-gradient-to-br from-[#2F80ED] to-[#0AA1FF] flex items-center justify-center transition-all group"
              style={{
                backdropFilter: 'blur(20px)',
                border: '1.5px solid rgba(255,255,255,0.3)',
                boxShadow: '0 8px 32px rgba(47,128,237,0.4), 0 20px 60px rgba(10,161,255,0.2), inset 0 2px 0 rgba(255,255,255,0.3)',
              }}
              whileHover={{ 
                scale: 1.05,
                boxShadow: '0 12px 48px rgba(47,128,237,0.5), 0 24px 80px rgba(10,161,255,0.3), inset 0 2px 0 rgba(255,255,255,0.4)',
              }}
              whileTap={{ scale: 0.95 }}
              transition={{ type: "spring", stiffness: 400, damping: 17 }}
            >
              {/* Inner highlight gradient */}
              <div className="absolute inset-0 rounded-full bg-gradient-to-br from-white/30 via-white/10 to-transparent" />

              {/* Animated shimmer effect */}
              <motion.div
                className="absolute inset-0 rounded-full"
                style={{
                  background: 'linear-gradient(135deg, transparent 0%, rgba(255,255,255,0.2) 50%, transparent 100%)',
                }}
                animate={{
                  rotate: [0, 360],
                }}
                transition={{
                  duration: 3,
                  repeat: Infinity,
                  ease: "linear"
                }}
              />

              <AnimatePresence mode="wait">
                {isPlaying ? (
                  <motion.div
                    key="pause"
                    initial={{ scale: 0, rotate: -90 }}
                    animate={{ scale: 1, rotate: 0 }}
                    exit={{ scale: 0, rotate: 90 }}
                    transition={{ type: "spring", stiffness: 300, damping: 20 }}
                  >
                    <Pause className="w-12 h-12 text-white fill-white relative z-10" />
                  </motion.div>
                ) : (
                  <motion.div
                    key="play"
                    initial={{ scale: 0, rotate: -90 }}
                    animate={{ scale: 1, rotate: 0 }}
                    exit={{ scale: 0, rotate: 90 }}
                    transition={{ type: "spring", stiffness: 300, damping: 20 }}
                  >
                    <Play className="w-12 h-12 text-white fill-white relative z-10 ml-1" />
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.button>
          </div>

          {/* Label */}
          <motion.div 
            className="mt-8 text-center"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
          >
            <div className="inline-block px-6 py-3 rounded-2xl bg-white/50 backdrop-blur-xl border border-white/30 shadow-lg">
              <p className="text-sm text-gray-700">Active State · Blur 20px · Shadow 32px</p>
              <p className="text-xs text-gray-500 mt-1">#2F80ED → #0AA1FF gradient</p>
            </div>
          </motion.div>
        </div>
      </div>
    );
  }

  return (
    <motion.div 
      className="w-full h-[800px] relative flex flex-col"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      {/* Top Header - Frosted Glass */}
      <motion.div 
        className="w-full px-6 py-5 rounded-3xl mb-4 relative overflow-hidden"
        style={{
          backdropFilter: 'blur(24px)',
          background: 'rgba(255,255,255,0.5)',
          border: '1.5px solid rgba(255,255,255,0.2)',
          boxShadow: 'inset 0 1px 0 0 rgba(255,255,255,0.6), 0 4px 16px rgba(47,128,237,0.08)',
        }}
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
      >
        {/* Subtle gradient overlay */}
        <div className="absolute inset-0 bg-gradient-to-br from-white/20 via-transparent to-[#2F80ED]/5 pointer-events-none" />

        <div className="flex items-center justify-between relative z-10">
          <h1 className="text-gray-800">Now Playing</h1>
          <motion.button 
            className="w-10 h-10 rounded-full bg-white/50 backdrop-blur-md flex items-center justify-center transition-all"
            whileHover={{ 
              scale: 1.05, 
              backgroundColor: 'rgba(255,255,255,0.7)',
              boxShadow: '0 4px 12px rgba(47,128,237,0.15)'
            }}
            whileTap={{ scale: 0.95 }}
          >
            <Search className="w-5 h-5 text-gray-700" />
          </motion.button>
        </div>
      </motion.div>

      {/* Album Art Banner - Large Frosted Card */}
      <motion.div 
        className="w-full px-6 py-6 rounded-[28px] mb-6 relative overflow-hidden"
        style={{
          backdropFilter: 'blur(26px)',
          background: 'rgba(255,255,255,0.45)',
          border: '1.5px solid rgba(255,255,255,0.2)',
          boxShadow: '0 12px 40px rgba(47,128,237,0.18), inset 0 1px 0 0 rgba(255,255,255,0.7)',
        }}
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ delay: 0.2, type: "spring", stiffness: 200, damping: 20 }}
      >
        {/* Layered gradient overlays */}
        <div className="absolute inset-0 bg-gradient-to-br from-white/10 via-transparent to-transparent pointer-events-none" />
        <div className="absolute inset-0 bg-gradient-to-tl from-[#2F80ED]/5 via-transparent to-transparent pointer-events-none" />

        <div className="relative aspect-video rounded-2xl overflow-hidden shadow-[0_12px_32px_rgba(0,0,0,0.15)]">
          {/* Radial gradient overlay with animation */}
          <motion.div 
            className="absolute inset-0 bg-gradient-radial from-transparent via-transparent to-[#2F80ED]/15"
            animate={{
              opacity: [0.8, 1, 0.8],
            }}
            transition={{
              duration: 3,
              repeat: Infinity,
              ease: "easeInOut"
            }}
          />
          <ImageWithFallback
            src="https://images.unsplash.com/photo-1614680376573-df3480f0c6ff?w=800&q=80"
            alt="Album Cover"
            className="w-full h-full object-cover"
          />

          {/* Subtle inner border highlight */}
          <div className="absolute inset-0 rounded-2xl border border-white/20 pointer-events-none" />
        </div>
      </motion.div>

      {/* Main Player Card - Central Frosted Glass */}
      <motion.div 
        className="w-full px-6 py-8 rounded-[24px] flex-1 relative overflow-hidden"
        style={{
          backdropFilter: 'blur(24px)',
          background: 'rgba(255,255,255,0.55)',
          border: '1.5px solid rgba(255,255,255,0.25)',
          boxShadow: '0 16px 56px rgba(47,128,237,0.15), inset 0 1px 0 0 rgba(255,255,255,0.8)',
        }}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.3, type: "spring", stiffness: 200, damping: 20 }}
      >
        {/* Multi-layer gradient overlays */}
        <div className="absolute inset-0 bg-gradient-to-br from-white/20 via-transparent to-transparent pointer-events-none" />
        <div className="absolute inset-0 bg-gradient-to-tl from-[#0AA1FF]/5 via-transparent to-[#2F80ED]/5 pointer-events-none" />

        <div className="relative z-10">
          {/* Song Info */}
          <motion.div 
            className="mb-6"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.4 }}
          >
            <h2 className="text-gray-900 mb-2">Midnight Dreams</h2>
            <p className="text-gray-600">Luna Eclipse</p>
          </motion.div>

          {/* Waveform Visualization */}
          <motion.div 
            className="mb-6"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: 0.5 }}
          >
            <div className="flex items-end justify-between h-16 gap-1">
              {Array.from({ length: 40 }).map((_, i) => {
                const baseHeight = 30 + Math.sin(i * 0.3) * 30 + Math.random() * 40;
                const isPast = (i / 40) * 100 < progress;
                const isActive = Math.abs((i / 40) * 100 - progress) < 3;

                return (
                  <motion.div
                    key={i}
                    className="flex-1 rounded-full"
                    style={{
                      background: isPast 
                        ? 'linear-gradient(to top, #0AA1FF, #2F80ED)' 
