````typescript name=src/components/common/GlassCard.tsx
import React from 'react';
import { View, StyleSheet } from 'react-native';
import { BlurView } from 'expo-blur';
import { RADII, COLORS, SHADOWS } from '../../design/tokens';

type Props = {
  children?: React.ReactNode;
  intensity?: number; // 0–100
  radius?: number;
  padding?: number;
  style?: any;
};

export const GlassCard: React.FC<Props> = ({
  children,
  intensity = 20,
  radius = RADII.lg,
  padding = 16,
  style,
}) => {
  return (
    <View style={[styles.container, { borderRadius: radius }, style]}>
      <BlurView intensity={intensity} tint="light" style={[styles.blur, { borderRadius: radius }]} />
      <View style={[styles.inner, { borderRadius: radius, padding }]}>
        {children}
      </View>
      <View style={[styles.border, { borderRadius: radius }]} />
      <View style={[styles.topHighlight, { borderRadius: radius }]} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    overflow: 'hidden',
    position: 'relative',
    backgroundColor: 'rgba(255,255,255,0.45)',
    ...SHADOWS.card,
  },
  blur: {
    ...StyleSheet.absoluteFillObject,
  },
  inner: {
    position: 'relative',
  },
  border: {
    ...StyleSheet.absoluteFillObject,
    borderWidth: 1,
    borderColor: COLORS.glassBorder,
  },
  topHighlight: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: 1,
    backgroundColor: COLORS.glassHighlight,
  },
});
