Play button with Moti/Reanimated
````typescript name=src/components/Player/PlayButton.tsx
import React from 'react';
import { View, Pressable, StyleSheet } from 'react-native';
import { MotiView } from 'moti';
import { LinearGradient } from 'expo-linear-gradient';
import Icon from 'react-native-vector-icons/Feather'; // or lucide-react-native
import { COLORS, RADII, SHADOWS } from '../../design/tokens';

type Props = {
  isPlaying: boolean;
  onToggle: () => void;
  size?: number; // visual diameter
};

export const PlayButton: React.FC<Props> = ({ isPlaying, onToggle, size = 80 }) => {
  return (
    <View style={{ width: size, height: size }}>
      {/* Pulsing glow */}
      {isPlaying && (
        <MotiView
          from={{ opacity: 0.3, scale: 1 }}
          animate={{ opacity: 0.6, scale: 1.2 }}
          transition={{ type: 'timing', duration: 2000, loop: true }}
          style={[StyleSheet.absoluteFill, styles.glow]}
        />
      )}

      <Pressable onPress={onToggle} style={({ pressed }) => [
        styles.button,
        {
          width: size,
          height: size,
          borderRadius: size / 2,
          transform: [{ scale: pressed ? 0.96 : 1 }],
        },
      ]}>
        {/* Gradient fill */}
        <LinearGradient
          colors={[COLORS.primaryBlue, COLORS.accentBlue]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={[StyleSheet.absoluteFill, { borderRadius: size / 2 }]}
        />

        {/* Inner highlight overlay */}
        <View
          style={[
            StyleSheet.absoluteFill,
            { borderRadius: size / 2, backgroundColor: 'rgba(255,255,255,0.15)' },
          ]}
        />

        <Icon
          name={isPlaying ? 'pause' : 'play'}
          size={size * 0.35}
          color="#FFFFFF"
          style={{ alignSelf: 'center', marginTop: size * 0.325 }}
        />
      </Pressable>
    </View>
  );
};

const styles = StyleSheet.create({
  button: {
    borderWidth: 2,
    borderColor: 'rgba(255,255,255,0.35)',
    ...SHADOWS.button,
  },
  glow: {
    borderRadius: RADII.round,
    backgroundColor: 'rgba(47,128,237,0.4)',
    filter: undefined, // RN doesn’t support CSS filters; glow simulated via opacity/scale
  },
});
````

Waveform visualization (deterministic, performant)
- Avoid random() every render. Precompute a sinusoidal array and animate amplitude on “playing”.
````typescript name=src/components/Player/Waveform.tsx
import React, { useMemo } from 'react';
import { View, StyleSheet } from 'react-native';
import { MotiView } from 'moti';
import { COLORS } from '../../design/tokens';

type Props = {
  bars?: number;
  progress: number; // 0–100
  isPlaying: boolean;
};

export const Waveform: React.FC<Props> = ({ bars = 40, progress, isPlaying }) => {
  const baseHeights = useMemo(() => {
    return Array.from({ length: bars }, (_, i) => 30 + Math.sin(i * 0.3) * 30 + 20); // %
  }, [bars]);

  return (
    <View style={styles.row}>
      {baseHeights.map((h, i) => {
        const pct = (i / bars) * 100;
        const isPast = pct < progress;
        const isActive = Math.abs(pct - progress) < 3;

        return (
          <MotiView
            key={i}
            from={{ height: `${h}%`, opacity: isPast ? 1 : 0.6 }}
            animate={{
              height: `${isPlaying && isActive ? h + 10 : h}%`,
              opacity: isPast ? 1 : 0.6,
            }}
            transition={{
              type: 'timing',
              duration: isPlaying && isActive ? 300 : 250,
              loop: isPlaying && isActive,
              direction: 'alternate',
            }}
            style={[
              styles.bar,
              {
                backgroundColor: isPast ? undefined : 'rgba(47,128,237,0.15)',
              },
            ]}
          />
        );
      })}
    </View>
  );
};

const styles = StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'flex-end', height: 64, gap: 4 },
  bar: {
    flex: 1,
    borderRadius: 999,
    backgroundColor: undefined,
  },
});
````

