import React, { useEffect } from 'react';
import { StyleSheet, Pressable, View, Platform } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';
import Svg, { Defs, RadialGradient, Stop, Circle } from 'react-native-svg';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
  interpolate,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';
import { colors, gradients, radii, shadows, touchTargetMinSize, animation } from '../utils/tokens';

interface PlayButtonProps {
  isPlaying: boolean;
  onPress: () => void;
  size?: number;
  accessibilityLabel?: string;
}

/**
 * PlayButton - Gradient play/pause button with pulsing glow animation when playing.
 * Uses Reanimated for smooth 60fps animations.
 */
export default function PlayButton({
  isPlaying,
  onPress,
  size = 64,
  accessibilityLabel,
}: PlayButtonProps) {
  // Shared value for pulsing glow animation (0 to 1)
  const glowProgress = useSharedValue(0);
  // Shared value for press scale animation
  const pressScale = useSharedValue(1);

  // Start/stop pulsing animation based on playing state
  useEffect(() => {
    if (isPlaying) {
      glowProgress.value = withRepeat(
        withSequence(
          withTiming(1, { duration: 1000, easing: Easing.inOut(Easing.ease) }),
          withTiming(0, { duration: 1000, easing: Easing.inOut(Easing.ease) })
        ),
        -1, // infinite repeat
        false
      );
    } else {
      cancelAnimation(glowProgress);
      glowProgress.value = withTiming(0, { duration: animation.duration.normal });
    }
  }, [isPlaying, glowProgress]);

  // Animated style for the glow effect
  const glowStyle = useAnimatedStyle(() => {
    const scale = interpolate(glowProgress.value, [0, 1], [1, 1.15]);
    const opacity = interpolate(glowProgress.value, [0, 1], [0.3, 0.6]);
    return {
      transform: [{ scale }],
      opacity,
    };
  });

  // Animated style for press feedback
  const buttonStyle = useAnimatedStyle(() => ({
    transform: [{ scale: pressScale.value }],
  }));

  const handlePressIn = () => {
    pressScale.value = withTiming(0.92, { duration: 100 });
  };

  const handlePressOut = () => {
    pressScale.value = withTiming(1, { duration: 150 });
  };

  const iconSize = size * 0.4;
  const glowSize = size * 2.5; // Large soft glow area

  return (
    <Pressable
      onPress={onPress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      accessibilityLabel={accessibilityLabel || (isPlaying ? 'Pause' : 'Play')}
      accessibilityRole="button"
      accessibilityState={{ checked: isPlaying }}
      style={[styles.wrapper, { width: Math.max(size, touchTargetMinSize), height: Math.max(size, touchTargetMinSize) }]}
    >
      {/* Glow effect layer (SVG Gradient for true blur effect on all platforms) */}
      <Animated.View
        style={[
          {
            position: 'absolute',
            width: glowSize,
            height: glowSize,
            alignItems: 'center',
            justifyContent: 'center',
            pointerEvents: 'none', // Ensure clicks pass through to button
          },
          glowStyle,
        ]}
      >
        <Svg height={glowSize} width={glowSize} viewBox={`0 0 ${glowSize} ${glowSize}`}>
          <Defs>
            <RadialGradient
              id="glowGrad"
              cx="50%"
              cy="50%"
              rx="50%"
              ry="50%"
              fx="50%"
              fy="50%"
              gradientUnits="userSpaceOnUse"
            >
              <Stop offset="20%" stopColor={colors.primaryBlue} stopOpacity="0.5" />
              <Stop offset="50%" stopColor={colors.primaryBlue} stopOpacity="0.2" />
              <Stop offset="100%" stopColor={colors.primaryBlue} stopOpacity="0" />
            </RadialGradient>
          </Defs>
          <Circle cx={glowSize / 2} cy={glowSize / 2} r={glowSize / 2} fill="url(#glowGrad)" />
        </Svg>
      </Animated.View>

      {/* Main button with gradient */}
      <Animated.View style={[styles.buttonOuter, { width: size, height: size }, buttonStyle]}>
        <LinearGradient
          colors={gradients.playButton}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={[
            styles.button,
            {
              width: size,
              height: size,
              borderRadius: size / 2,
              borderWidth: 1,
              borderColor: 'rgba(255,255,255,0.15)',
            }
          ]}
        >
          <View style={styles.iconContainer}>
            <Ionicons
              name={isPlaying ? "pause" : "play"}
              size={iconSize}
              color={colors.textWhite}
              style={!isPlaying ? { marginLeft: size * 0.1 } : undefined}
            />
          </View>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  wrapper: {
    alignItems: 'center',
    justifyContent: 'center',
    position: 'relative',
  },
  // glow style removed as it is now handled by SVG
  buttonOuter: {
    ...Platform.select({
      ios: shadows.playButton,
      android: shadows.playButton,
    }),
  },
  button: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  iconContainer: {
    alignItems: 'center',
    justifyContent: 'center',
  },
});

