  blurIntensityAndroid?: number; // intensity on Android fallback
  tint?: 'light' | 'dark' | 'default';
};

const GlassDrawer: React.FC<Props> = ({
  isOpen,
  onClose,
  onNavigate,
  widthPercent = 0.6,
  blurIntensityIOS = 90,
  blurIntensityAndroid = 30,
