            }
            start={{ x: 0, y: 0 }}
            end={{ x: 0, y: 1 }}
            style={styles.gradientOverlay}
          >
            <SafeAreaView edges={['top', 'left', 'bottom']} style={styles.safe}>
              <Animated.View style={[styles.innerContent, innerScaleStyle]}>
