        {/* Thin glass border edge */}
        <View
          pointerEvents="none"
          style={[
            styles.glassEdge,
            { borderRightColor: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)' },
          ]}
        />
      </Animated.View>
    </Animated.View>
  );
};

