```typescript name=src/screens/AboutScreen.tsx
import React from 'react';
import {
  View,
  Text,
  ScrollView,
  StyleSheet,
  Linking,
  TouchableOpacity,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Feather } from '@expo/vector-icons';
import Constants from 'expo-constants';
import { getColors, spacing } from '../theme/designTokens';

const openLink = async (url: string) => {
  try {
    const supported = await Linking.canOpenURL(url);
    if (supported) {
      await Linking.openURL(url);
    }
  } catch {
    // Silently ignore to avoid crashes
  }
};

export default function AboutScreen() {
  const isDark = false; // keep simple; app header handles theme
  const colors = getColors?.(isDark) ?? {
    text: '#111',
    muted: 'rgba(0,0,0,0.6)',
    border: 'rgba(0,0,0,0.1)',
    bg: '#fff',
  };

  const appName =
    Constants?.expoConfig?.name ??
    Constants?.manifest?.name ??
    'Coffee Native';
  const appVersion =
    Constants?.expoConfig?.version ??
    Constants?.manifest?.version ??
    '1.0.0';
  const sdkVersion =
    (Constants?.expoConfig as any)?.sdkVersion ??
    Constants?.manifest?.sdkVersion ??
    'unknown';

  return (
    <SafeAreaView style={[styles.safe, { backgroundColor: colors.bg ?? '#fff' }]}>
      <ScrollView contentContainerStyle={styles.container}>
        {/* Header */}
        <View style={styles.header}>
          <Feather name="info" size={22} color={colors.text} />
          <Text style={[styles.title, { color: colors.text }]}>About</Text>
        </View>

        {/* App overview */}
        <View style={styles.card}>
          <Text style={[styles.appName, { color: colors.text }]}>{appName}</Text>
          <Text style={[styles.muted, { color: colors.muted }]}>
            A simple music app with a clean player, profile, and drawer navigation.
          </Text>
          <View style={styles.metaRow}>
            <MetaItem label="Version" value={appVersion} />
            <MetaItem label="Expo SDK" value={String(sdkVersion)} />
            <MetaItem label="Platform" value={Platform.OS} />
          </View>
        </View>

        {/* Links */}
        <View style={styles.section}>
          <Text style={[styles.sectionTitle, { color: colors.text }]}>Links</Text>
          <LinkItem
            label="Project Repository"
            icon="github"
            onPress={() =>
              openLink('https://github.com/EthanAdriano25505-code/coffee-native')
            }
            colors={colors}
          />
          <LinkItem
            label="Privacy Policy"
            icon="shield"
            onPress={() => openLink('https://example.com/privacy')}
            colors={colors}
          />
          <LinkItem
            label="Terms of Use"
            icon="file-text"
            onPress={() => openLink('https://example.com/terms')}
            colors={colors}
          />
          <LinkItem
            label="Contact Support"
            icon="mail"
            onPress={() => openLink('mailto:support@example.com')}
            colors={colors}
          />
        </View>

        {/* Credits / Acknowledgments */}
        <View style={styles.section}>
          <Text style={[styles.sectionTitle, { color: colors.text }]}>Credits</Text>
          <Text style={[styles.muted, { color: colors.muted }]}>
            Design and development by Saw K Za.
          </Text>
          <Text style={[styles.muted, { color: colors.muted, marginTop: spacing.xs }]}>
            Built with React Native, Expo, and React Navigation.
          </Text>
        </View>

