import React, { useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Dimensions,
  Platform,
  useColorScheme,
  Pressable,
} from 'react-native';
import { BlurView } from 'expo-blur';
import { LinearGradient } from 'expo-linear-gradient';
import { Feather } from '@expo/vector-icons';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  interpolate,
  Extrapolate,
} from 'react-native-reanimated';
import { getColors, spacing } from '../theme/designTokens';
import { SafeAreaView } from 'react-native-safe-area-context';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

type Props = {
  isOpen: boolean;
  onClose: () => void;
  onNavigate?: (screen: string) => void;
  widthPercent?: number; // default 0.75 (75% width)
  blurIntensityIOS?: number; // intensity on iOS
  blurIntensityAndroid?: number; // intensity on Android fallback
  tint?: 'light' | 'dark' | 'default';
};

const GlassDrawer: React.FC<Props> = ({
  isOpen,
  onClose,
  onNavigate,
  widthPercent = 0.6,
  blurIntensityIOS = 90,
  blurIntensityAndroid = 30,
  tint = 'default',
}) => {
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  const colors = getColors?.(!!isDark) ?? {
    text: isDark ? '#fff' : '#111',
    muted: isDark ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.5)',
  };

  const DRAWER_WIDTH = Math.round(SCREEN_WIDTH * widthPercent);

  // reanimated shared values
  const translateX = useSharedValue(-DRAWER_WIDTH); // start off-screen to the left
  const overlayOpacity = useSharedValue(0);
  const contentScale = useSharedValue(0.98);

  useEffect(() => {
    if (isOpen) {
      // open
      translateX.value = withSpring(0, {
        damping: 20,
        stiffness: 100,
        mass: 0.8,
      });
      overlayOpacity.value = withTiming(1, { duration: 300 });
      contentScale.value = withTiming(1, { duration: 300 });
    } else {
      // close
      translateX.value = withSpring(-DRAWER_WIDTH, {
        damping: 20,
        stiffness: 120,
        mass: 0.8,
      });
      overlayOpacity.value = withTiming(0, { duration: 220 });
      contentScale.value = withTiming(0.98, { duration: 220 });
    }
  }, [isOpen, DRAWER_WIDTH]);

  const drawerStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
  }));

  const overlayStyle = useAnimatedStyle(() => ({
    opacity: overlayOpacity.value,
  }));

  // subtle parallax effect for interior content (optional)
  const innerScaleStyle = useAnimatedStyle(() => ({
    transform: [{ scale: interpolate(contentScale.value, [0.98, 1], [0.995, 1], Extrapolate.CLAMP) }],
  }));

  const handleNavigate = (screen: string) => {
    // close then navigate via onNavigate (keep UI responsive)
    onClose();
    setTimeout(() => {
      onNavigate?.(screen);
    }, 260);
  };

  if (!isOpen && overlayOpacity.value === 0) {
    // completely closed — render nothing to avoid capturing touches
    return null;
  }

  const blurIntensity = Platform.OS === 'ios' ? blurIntensityIOS : blurIntensityAndroid;
  const blurTint = tint === 'default' ? (isDark ? 'dark' : 'light') : tint;

  const menuItems = [
    { id: 'home', label: 'Home', icon: 'home', screen: 'Home' },
    { id: 'profile', label: 'Profile', icon: 'user', screen: 'Profile' },
    { id: 'settings', label: 'Settings', icon: 'settings', screen: 'Settings' },
    { id: 'about', label: 'About', icon: 'info', screen: 'About' },
  ];

  return (
    <Animated.View style={[styles.container, { zIndex: 9999 }]}>
      {/* Overlay: limit overlay to the screen area NOT covered by the drawer so it never intercepts drawer touchables */}
      <Pressable
        style={[StyleSheet.absoluteFill, { left: DRAWER_WIDTH }]}
        onPress={onClose}
        pointerEvents={isOpen ? 'auto' : 'none'}
      >
        <Animated.View
          // give the overlay a zIndex lower than the drawer to make stacking explicit
          style={[
            styles.overlay,
            overlayStyle,
            { zIndex: 10000, backgroundColor: isDark ? 'rgba(0,0,0,0.55)' : 'rgba(0,0,0,0.45)' },
          ]}
        />
      </Pressable>

      {/* Drawer surface (ensure it sits above the overlay) */}
      <Animated.View
        style={[
          styles.drawer,
          drawerStyle,
          {
            width: DRAWER_WIDTH,
            height: SCREEN_HEIGHT,
            left: 0,
            zIndex: 10001,
            shadowColor: '#000',
            shadowOpacity: isDark ? 0.5 : 0.28,
            shadowOffset: { width: 4, height: 0 },
            shadowRadius: 18,
            elevation: 28,
          },
        ]}
      >
        <BlurView intensity={blurIntensity} tint={blurTint} style={styles.blurContainer}>
          <LinearGradient
            colors={
              isDark
                ? ['rgba(25,25,25,0.78)', 'rgba(18,18,18,0.92)']
                : ['rgba(255,255,255,0.78)', 'rgba(245,245,245,0.92)']
            }
            start={{ x: 0, y: 0 }}
            end={{ x: 0, y: 1 }}
            style={styles.gradientOverlay}
          >
            <SafeAreaView edges={['top', 'left', 'bottom']} style={styles.safe}>
              <Animated.View style={[styles.innerContent, innerScaleStyle]}>
                {/* Header */}
                <View style={styles.header}>
                  <Text style={[styles.headerTitle, { color: colors.text }]}>Menu</Text>
                  <TouchableOpacity
                    onPress={onClose}
                    style={styles.closeButton}
                    accessibilityLabel="Close menu"
                    accessibilityRole="button"
                  >
                    <Feather name="x" size={22} color={colors.text} />
                  </TouchableOpacity>
                </View>

                {/* Items */}
                <View style={styles.menuItems}>
                  {menuItems.map((item) => (
                    <TouchableOpacity
                      key={item.id}
                      style={{
                        marginBottom: spacing.sm,
                        borderRadius: 14,
                        // Shadow for the "lifted" glass look
                        shadowColor: '#000',
                        shadowOffset: { width: 0, height: 4 },
                        shadowOpacity: isDark ? 0.4 : 0.1,
                        shadowRadius: 8,
                        elevation: 4,
                        backgroundColor: 'transparent',
                      }}
                      onPress={() => handleNavigate(item.screen)}
                      accessibilityLabel={item.label}
                      activeOpacity={0.75}
                    >
                      <BlurView
                        intensity={Platform.OS === 'ios' ? 80 : 40}
                        tint={isDark ? 'dark' : 'light'}
                        style={{
                          borderRadius: 14,
                          overflow: 'hidden',
                          borderWidth: 1,
                          borderColor: isDark ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.6)',
                          backgroundColor: 'transparent',
                        }}
                      >
                        <LinearGradient
                          colors={
                            isDark
                              ? ['rgba(255,255,255,0.1)', 'rgba(255,255,255,0.05)']
                              : ['rgba(255,255,255,0.7)', 'rgba(255,255,255,0.3)']
                          }
                          start={{ x: 0, y: 0 }}
                          end={{ x: 0, y: 1 }}
                          style={{
                            flexDirection: 'row',
                            alignItems: 'center',
                            paddingVertical: spacing.md,
                            paddingHorizontal: spacing.sm,
                            minHeight: 56,
                          }}
                        >
                          <Feather name={item.icon as any} size={20} color={colors.text} style={styles.menuIcon} />
                          <Text style={[styles.menuLabel, { color: colors.text }]}>{item.label}</Text>
                          <Feather name="chevron-right" size={18} color={colors.muted ?? 'rgba(0,0,0,0.4)'} />
                        </LinearGradient>
                      </BlurView>
                    </TouchableOpacity>
                  ))}
                </View>

                {/* Footer */}
                <View style={styles.footer}>
                  <Text style={[styles.footerText, { color: colors.muted }]}>Music App v1.0
by Saw K Za</Text>
                </View>
              </Animated.View>
            </SafeAreaView>
          </LinearGradient>
        </BlurView>

        {/* Thin glass border edge */}
        <View
          pointerEvents="none"
          style={[
            styles.glassEdge,
            { borderRightColor: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)' },
          ]}
        />
      </Animated.View>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  container: {
    ...StyleSheet.absoluteFillObject,
  },
  overlay: {
    ...StyleSheet.absoluteFillObject,
  },

  // Drawer shell
  drawer: {
    position: 'absolute',
    top: 0,
    overflow: 'hidden',
    // rounded "liquid" edges like iPhone sheets
    borderTopRightRadius: 28,
    borderBottomRightRadius: 28,
    // subtle outer shadow to lift it above the backdrop
    shadowColor: '#000',
    shadowOffset: { width: 6, height: 10 },
    shadowOpacity: 0.18,
    shadowRadius: 30,
    elevation: 30,
    backgroundColor: 'transparent',
  },

  // Keep blur container rounded so blur respects the corner radius
  blurContainer: {
    flex: 1,
    overflow: 'hidden',
    borderTopRightRadius: 28,
    borderBottomRightRadius: 28,
  },

  // gradient overlay stretches full height; we add padding in inner content
  gradientOverlay: {
    flex: 1,
  },

  safe: {
    flex: 1,
  },

  // Inner content gets more roomy padding and a soft parallax-friendly layout
  innerContent: {
    flex: 1,
    paddingHorizontal: spacing.md * 1.5,
    paddingTop: spacing.md * 1.5,
    paddingBottom: spacing.md,
    // ensure children don't paint outside rounded corners
    overflow: 'hidden',
  },

  // Header: larger title with frosted subtle text shadow for depth
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: spacing.md,
    paddingBottom: spacing.sm,
    marginBottom: spacing.sm,
  },
  headerTitle: {
    fontSize: 24,
    fontWeight: '900',
    letterSpacing: 0.2,
    // subtle frosted glow/shadow
    textShadowColor: 'rgba(0,0,0,0.08)',
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 6,
  },
  closeButton: {
    padding: spacing.sm,
    borderRadius: 14,
    // soft translucent hit target reminiscent of iOS controls
    backgroundColor: 'rgba(255,255,255,0.03)',
  },

  // Menu list area
  menuItems: {
    flex: 1,
    paddingTop: spacing.sm,
  },

  // Each item has a pill-like shape with a light glass surface and inner shadow
  menuItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: spacing.md,
    paddingHorizontal: spacing.sm,
    marginBottom: spacing.sm,
    borderRadius: 14,
    borderWidth: 1,
    minHeight: 56,
    // softer rounded look + subtle inner elevation
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 3 },
    shadowOpacity: 0.06,
    shadowRadius: 8,
    elevation: 2,
    // fallback translucent fill — specific colors are provided inline depending on theme
    backgroundColor: 'transparent',
  },
  menuIcon: {
    marginRight: spacing.md,
    opacity: 0.95,
  },
  menuLabel: {
    fontSize: 16,
    fontWeight: '700',
    flex: 1,
  },

  // Footer with subtle divider and lighter text
  footer: {
    paddingVertical: spacing.md,
    alignItems: 'center',
    borderTopWidth: 1,
    borderTopColor: 'rgba(255,255,255,0.03)',
    marginTop: spacing.sm,
  },
  footerText: {
    fontSize: 12,
    opacity: 0.8,
    letterSpacing: 0.2,
  },

  // Thin glass edge to emphasize the sheet boundary; slightly blurred look via transparency
  glassEdge: {
    position: 'absolute',
    top: 0,
    bottom: 0,
    right: -1,
    width: 2,
    borderRightWidth: 1,
    opacity: 0.95,
    // neutral color used inline for light/dark adjustments; keep space for a highlight
    backgroundColor: 'transparent',
    // subtle highlight (will blend with the gradient behind it)
    shadowColor: '#fff',
    shadowOffset: { width: -1, height: 0 },
    shadowOpacity: 0.025,
    shadowRadius: 6,
    elevation: 0,
  },
});

export default GlassDrawer;

import React, { useEffect, useState, useCallback, useMemo, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Dimensions,
  useColorScheme,
  FlatList,
  ListRenderItem,
  Animated,
  Pressable,
  Easing,
  Platform,
  TouchableWithoutFeedback,
  ScrollView,
} from 'react-native';
import {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  Easing as ReanimatedEasing,
} from 'react-native-reanimated';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useNavigation } from '@react-navigation/native';
import HamburgerButton from '../components/HamburgerButton';

import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { RootStackParamList } from '../navigation/types';
import { usePlayback } from '../contexts/PlaybackContext';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { supabase } from '../utils/supabase';
import SongCard from '../components/SongCard';
import { Feather } from '@expo/vector-icons';
import BannerIllustration from '../assets/BannerIllustration';
import BannerSlider from '../components/BannerSlider';
import SearchBar from '../components/SearchBar';
import RemoteImage from '../components/RemoteImage';
import { spacing, radii, sizes, elevation, getColors } from '../theme/designTokens';
import { tokens } from '../theme/designTokens';
import { BlurView } from 'expo-blur';
import { LinearGradient } from 'expo-linear-gradient';
import GlassDrawer from '../components/GlassDrawer';

const { width, height } = Dimensions.get('window');
const isLargeScreen = Math.max(width, height) >= 768;
const PLAYER_HEIGHT = isLargeScreen ? 88 : 72;

const SCREEN_WIDTH = width;
const BASE_PADDING = spacing.md;
const BANNER_HEIGHT = Math.round(SCREEN_WIDTH * (isLargeScreen ? 0.35 : 0.45));
const SLIDE_WIDTH = Math.round(SCREEN_WIDTH - BASE_PADDING * 2);

type HomeNavProp = NativeStackNavigationProp<RootStackParamList, 'Home'>;

type Song = {
  id: string | number;
  title: string;
  artist?: string | null;
  audio_url?: string | null;
  cover_url?: string | null;
  created_at?: string | null;
};

const DRAWER_WIDTH_PERCENT = 0.75;
const DRAWER_WIDTH = Math.round(SCREEN_WIDTH * DRAWER_WIDTH_PERCENT);
const BLUR_INTENSITY_IOS = 95;
const BLUR_INTENSITY_ANDROID = 40;

const HomeScreen: React.FC = () => {
  if (__DEV__) console.log('HomeScreen loaded: src/screens/HomeScreen.tsx');

  const hookNav = useNavigation<HomeNavProp>();
  const navigation = useNavigation<any>();
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  const colors = getColors(isDark);
  const insets = useSafeAreaInsets();

  const { currentSong: ctxSong, isPlaying: ctxPlaying, positionMillis, durationMillis, play, pause, next, prev, togglePlay } = usePlayback();

  const [songs, setSongs] = useState<Song[]>([]);
  const [currentSong, setCurrentSong] = useState<Song | null>((ctxSong as Song) ?? null);
  const [isPlaying, setIsPlaying] = useState<boolean>(!!ctxPlaying);
  const [activeFilter, setActiveFilter] = useState('All');

  // Drawer state (local)
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);

  useEffect(() => setCurrentSong((ctxSong as Song) ?? null), [ctxSong]);
  useEffect(() => setIsPlaying(!!ctxPlaying), [ctxPlaying]);

  useEffect(() => {
    if (__DEV__) console.log('player cover_url:', currentSong?.cover_url);
  }, [currentSong]);

  // mini-player progress animation
  const progressAnim = React.useRef(new Animated.Value(0)).current;
  React.useEffect(() => {
    const progressPercent = durationMillis && durationMillis > 0 ? (positionMillis / durationMillis) * 100 : 0;
    Animated.timing(progressAnim, {
      toValue: progressPercent,
      duration: 300,
      easing: Easing.out(Easing.quad),
      useNativeDriver: false,
    }).start();
  }, [positionMillis, durationMillis, progressAnim]);

  const fetchSongs = useCallback(async () => {
    try {
      const { data, error } = await supabase
        .from('songs')
        .select('id,title,artist,audio_url,cover_url,teaser_url,is_available,created_at,popularity')
        .order('created_at', { ascending: false })
        .limit(30);

      if (__DEV__) console.log('HomeScreen fetch result:', { data, error });

      if (error) {
        console.warn('fetchSongs error:', error);
        setSongs([]);
      } else {
        setSongs((data as Song[]) || []);
      }
    } catch (err) {
      console.warn('fetchSongs exception:', err);
      setSongs([]);
    }
  }, []);

  useEffect(() => {
    fetchSongs();
  }, [fetchSongs]);

  const handlePressSong = useCallback(async (song: Song) => {
    setCurrentSong(song);
    const uri = song.audio_url ? { uri: song.audio_url } : undefined;
    const payload = {
      id: song.id,
      title: song.title,
      artist: song.artist ?? undefined,
      cover_url: song.cover_url ?? undefined,
      uri,
    };
    await play(payload);
  }, [play]);

  const handlePlayPause = useCallback(async () => {
    if (isPlaying) await pause();
    else if (currentSong) {
      const uri = currentSong.audio_url ? { uri: currentSong.audio_url } : undefined;
      const payload = {
        id: currentSong.id,
        title: currentSong.title,
        artist: currentSong.artist ?? undefined,
        cover_url: currentSong.cover_url ?? undefined,
        uri,
      };
      await play(payload);
    }
  }, [isPlaying, pause, play, currentSong]);

  // Banners
  type BannerRow = { id: string | number; image_url?: string | null; title?: string | null; href?: string | null };
  const [banners, setBanners] = React.useState<BannerRow[]>([]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const { data, error } = await supabase
          .from('banners')
          .select('id, image_url, title, href, created_at')
          .order('created_at', { ascending: false })
          .limit(10);

        if (error) {
          console.warn('fetch banners error:', error);
        } else if (mounted && Array.isArray(data)) {
          setBanners(data as BannerRow[]);
        }
      } catch (err) {
        console.warn('fetch banners exception:', err);
      }
    })();
    return () => {
      mounted = false;
    };
  }, []);

  const bannerSlides = useMemo(() => {
    if (!banners || banners.length === 0) {
      return [
        {
          id: 'banner-1',
          component: (
            <View style={styles.bannerCard}>
              <BannerIllustration width={width - BASE_PADDING * 2} height={BANNER_HEIGHT - 24} />
            </View>
          ),
        },
        {
          id: 'banner-2',
          component: (
            <View style={styles.bannerCard}>
              <BannerIllustration width={width - BASE_PADDING * 2} height={BANNER_HEIGHT - 24} />
            </View>
          ),
        },
        {
          id: 'banner-3',
          component: (
            <View style={styles.bannerCard}>
              <BannerIllustration width={width - BASE_PADDING * 2} height={BANNER_HEIGHT - 24} />
            </View>
          ),
        },
      ];
    }

    return banners.map((b) => ({
      id: String(b.id),
      component: (
        <View style={{ borderRadius: 12, overflow: 'hidden', backgroundColor: '#f0f0f0' }}>
          <RemoteImage
            uri={b.image_url ?? null}
            width={SLIDE_WIDTH}
            height={BANNER_HEIGHT}
            placeholderText={b.title ?? 'Banner'}
            imageProps={{ resizeMode: 'cover' } as any}
          />
        </View>
      ),
    }));
  }, [banners]);

  const listHeaderElement = useMemo(() => {
    return (
      <View>
        <View style={[styles.bannerWrapper, { height: BANNER_HEIGHT }]}>
          <BannerSlider slides={bannerSlides} autoAdvanceMs={6000} height={BANNER_HEIGHT} />
        </View>

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={{ paddingHorizontal: spacing.md, paddingBottom: spacing.md, paddingTop: spacing.xs }}
          style={{ flexGrow: 0 }}
        >
          {['All', 'Playlists', 'Albums', 'Downloaded'].map((filter) => {
            const isActive = activeFilter === filter;
            return (
              <TouchableOpacity
                key={filter}
                onPress={() => setActiveFilter(filter)}
                activeOpacity={0.7}
                style={{
                  marginRight: spacing.sm,
                  borderRadius: radii.round,
                  // Shadow for the "lifted" glass look
                  shadowColor: '#000',
                  shadowOffset: { width: 0, height: 4 },
                  shadowOpacity: isDark ? 0.4 : 0.1,
                  shadowRadius: 8,
                  elevation: 4,
                  backgroundColor: 'transparent',
                }}
              >
                <BlurView
                  intensity={Platform.OS === 'ios' ? 80 : 40}
                  tint={isDark ? 'dark' : 'light'}
                  style={{
                    borderRadius: radii.round,
                    overflow: 'hidden',
                    borderWidth: 1,
                    borderColor: isActive
                      ? (isDark ? '#2F6DFD' : '#2F6DFD')
                      : (isDark ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.6)'),
                    backgroundColor: 'transparent',
                  }}
                >
                  <LinearGradient
                    colors={
                      isDark 
                        ? ['rgba(255,255,255,0.1)', 'rgba(255,255,255,0.05)'] 
                        : ['rgba(255,255,255,0.7)', 'rgba(255,255,255,0.3)']
                    }
                    start={{ x: 0, y: 0 }}
                    end={{ x: 0, y: 1 }}
                    style={{
                      paddingHorizontal: spacing.lg,
                      paddingVertical: 10,
                      flexDirection: 'row',
                      alignItems: 'center',
                      justifyContent: 'center',
                    }}
                  >
                    <Text
                      style={{
                        color: isActive
                          ? '#2F6DFD'
                          : (isDark ? '#E6EEF8' : '#111'),
                        fontWeight: isActive ? '700' : '600',
                        fontSize: 14,
                      }}
                    >
                      {filter}
                    </Text>
                  </LinearGradient>
                </BlurView>
              </TouchableOpacity>
            );
          })}
        </ScrollView>

        <View style={styles.sectionHeaderCompact}>
          <Text style={[styles.sectionTitle, isDark && styles.sectionTitleDark]}>Song List</Text>
          <TouchableOpacity onPress={() => hookNav.navigate('FullSongs')}>
            <Text style={styles.seeAll}>See all</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }, [bannerSlides, isDark, hookNav, activeFilter]);

  const onCardPress = useCallback((song: Song) => {
    const payload = {
      id: song.id,
      title: song.title,
      artist: song.artist ?? undefined,
      cover_url: song.cover_url ?? undefined,
      uri: song.audio_url ? { uri: song.audio_url } : undefined,
    };
    play(payload);
    navigation.navigate('Player', { song });
  }, [play, navigation]);

  const renderSongItem: ListRenderItem<Song> = useCallback(({ item }) => (
    <View style={{ paddingHorizontal: spacing.sm }}>
      <SongCard song={item} onPress={() => onCardPress(item)} />
    </View>
  ), [onCardPress]);

  const listFooter = songs.length > 0 ? <View style={{ height: PLAYER_HEIGHT + (insets.bottom ?? 0) + 12 }} /> : null;

  const openDrawer = useCallback(() => setIsDrawerOpen(true), []);
  const closeDrawer = useCallback(() => setIsDrawerOpen(false), []);

  const handleDrawerNavigate = useCallback((screen: string) => {
    // close then navigate
    setIsDrawerOpen(false);
    setTimeout(() => {
      try {
        (hookNav ?? navigation)?.navigate(screen as any);
      } catch (err) {
        if (__DEV__) console.warn('Navigation from drawer failed', err);
      }
    }, 260);
  }, [hookNav, navigation]);

  // (drawer animations removed) simple state-driven overlay handled by GlassDrawer

  // menu items (placeholder)
  const menuItems = [
    { id: 'home', label: 'Home', icon: 'home', screen: 'Home' },
    { id: 'profile', label: 'Profile', icon: 'user', screen: 'Profile' },
    { id: 'settings', label: 'Settings', icon: 'settings', screen: 'Settings' },
    { id: 'about', label: 'About', icon: 'info', screen: 'About' },
  ];

  return (
    <SafeAreaView
      style={[styles.safe, { backgroundColor: colors.background }, isDark && styles.safeDark, { position: 'relative' }]}
      edges={['left', 'right', 'bottom']}
    >
      {/* Header */}
      <View style={[styles.header, isDark && styles.headerDark, { paddingTop: insets.top + 3 }]}>
        <Text style={[styles.headerTitle, isDark && styles.headerTitleDark]}>Music</Text>
        <View style={styles.headerActions}>
          <SearchBar
            onPress={() => {
              if (__DEV__) console.log('Search tapped');
            }}
            placeholder="Search songs, artists..."
          />

          {/* Hamburger opens our Animated glass drawer (no reanimated dependency) */}
          <HamburgerButton
            onPress={() => {
              // open with animation
              openDrawer();
            }}
            color={isDark ? '#fff' : '#111'}
          />

          
        </View>
      </View>

      <FlatList
        data={songs}
        keyExtractor={(item) => String(item.id)}
        renderItem={renderSongItem}
        ListHeaderComponent={listHeaderElement}
        ListEmptyComponent={null}
        ListFooterComponent={listFooter}
        contentContainerStyle={{ backgroundColor: isDark ? '#000' : '#f7f7f8' }}
        ItemSeparatorComponent={() => <View style={styles.rowSeparator} />}
        showsVerticalScrollIndicator={false}
        initialNumToRender={8}
        windowSize={9}
        removeClippedSubviews={true}
      />

      {/* Mini-player */}
      {currentSong ? (
        <Pressable
          onPress={() => {
            (hookNav ?? navigation)?.navigate('Player' as any, { song: currentSong });
          }}
          style={[styles.playerBar, { height: PLAYER_HEIGHT, bottom: (insets.bottom ?? 0) + 6 }]}
          pointerEvents="box-none"
        >
          <View style={[styles.playerInner, isDark && styles.playerInnerDark]}>
            <View style={styles.playerLeft}>
              <RemoteImage
                uri={currentSong?.cover_url ?? null}
                width={48}
                height={48}
                style={styles.playerArtImage}
                placeholderText="Art"
              />

              <View style={styles.playerMeta}>
                <Text style={styles.playerTitle} numberOfLines={1}>{currentSong?.title ?? ''}</Text>
                <Text style={styles.playerArtist}>{currentSong?.artist ?? ''}</Text>

                <View style={styles.progressContainer}>
                  <Animated.View
                    style={[
                      styles.progressFill,
                      {
                        width: progressAnim.interpolate({
                          inputRange: [0, 100],
                          outputRange: ['0%', '100%'],
                          extrapolate: 'clamp',
                        }),
                      },
                    ]}
                  />
                </View>
              </View>
            </View>

            <View style={styles.playerControls}>
              <TouchableOpacity onPress={() => prev()} style={styles.controlBtn} accessibilityLabel="Previous">
                <Feather name="skip-back" size={20} color="#fff" />
              </TouchableOpacity>

              <TouchableOpacity
                onPress={() => {
                  setIsPlaying((p) => !p);
                  togglePlay();
                }}
                style={styles.playFab}
                accessibilityLabel={isPlaying ? 'Pause' : 'Play'}
              >
                <Feather name={isPlaying ? 'pause' : 'play'} size={24} color="#111" />
              </TouchableOpacity>

              <TouchableOpacity onPress={() => next()} style={styles.controlBtn} accessibilityLabel="Next">
                <Feather name="skip-forward" size={20} color="#fff" />
              </TouchableOpacity>
            </View>
          </View>
        </Pressable>
      ) : null}

      {/* Animated glass drawer (implemented inline so we avoid reanimated/worklets) */}
      {/*
        Behavior:
        - Drawer slides in from left covering ~75% width
        - Backdrop dims and is pressable to dismiss
        - Drawer interior uses BlurView + LinearGradient for premium glass look
      */}
      <GlassDrawer
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
        onNavigate={(screen) => {
          // Only allow safe, parameterless routes from the drawer
          const safeRoutes = ['Home', 'Profile', 'Settings', 'About'];
          if (safeRoutes.includes(screen)) {
            setIsDrawerOpen(false);
            try {
              (hookNav ?? navigation).navigate(screen as any);
            } catch (e) {
              if (__DEV__) console.warn('Drawer navigation failed', e);
            }
          } else {
            if (__DEV__) console.warn('Attempted unsafe drawer navigation to:', screen);
          }
        }}
      />
    </SafeAreaView>
  );
};

