    opacity: overlayOpacity.value,
  }));

  const innerScaleStyle = useAnimatedStyle(() => ({
    transform: [{ scale: interpolate(contentScale.value, [0.98, 1], [0.995, 1], Extrapolate.CLAMP) }],
  }));

  const handleNavigate = (screen: string) => {
    onClose();
    setTimeout(() => onNavigate?.(screen), 260);
  };

  if (!mounted) return null;

  const blurIntensity = Platform.OS === 'ios' ? blurIntensityIOS : blurIntensityAndroid;
  const blurTint = tint === 'default' ? (isDark ? 'dark' : 'light') : tint;

  const menuItems = [
    { id: 'home', label: 'Home', icon: 'home', screen: 'Home' },
    { id: 'profile', label: 'Profile', icon: 'user', screen: 'Profile' },
    { id: 'settings', label: 'Settings', icon: 'settings', screen: 'Settings' },
    { id: 'about', label: 'About', icon: 'info', screen: 'About' },
  ];

  return (
    <Animated.View
      style={[styles.container, { zIndex: 9999 }]}
      pointerEvents={isOpen ? 'auto' : 'none'}
    >
      {/* Overlay: extend 1px under the drawer edge to hide any highlight bleed */}
      <Pressable
        style={[StyleSheet.absoluteFill, { left: DRAWER_WIDTH - 1 }]}
        onPress={onClose}
        pointerEvents={isOpen ? 'auto' : 'none'}
      >
        <Animated.View
          style={[
            styles.overlay,
            overlayStyle,
            { zIndex: 10000, backgroundColor: isDark ? 'rgba(0,0,0,0.55)' : 'rgba(0,0,0,0.45)' },
          ]}
        />
      </Pressable>

      {/* Drawer surface */}
      <Animated.View
        style={[
          styles.drawer,
          drawerStyle,
          {
            width: DRAWER_WIDTH,
            height: SCREEN_HEIGHT,
            left: 0,
            zIndex: 10001,
            // tone down shadows to avoid right-side glow on Android
            shadowColor: '#000',
            shadowOpacity: isDark ? 0.35 : 0.18,
            shadowOffset: { width: 2, height: 2 },
            shadowRadius: 16,
            elevation: 12, // lower
          },
        ]}
      >
        <BlurView intensity={blurIntensity} tint={blurTint} style={styles.blurContainer}>
          <LinearGradient
            colors={
              isDark
                ? ['rgba(25,25,25,0.78)', 'rgba(18,18,18,0.90)']
                : ['rgba(255,255,255,0.62)', 'rgba(245,245,245,0.78)'] // slightly less bright
            }
            start={{ x: 0, y: 0 }}
            end={{ x: 0, y: 1 }}
            style={styles.gradientOverlay}
          >
            <SafeAreaView edges={['top', 'left', 'bottom']} style={styles.safe}>
              <Animated.View style={[styles.innerContent, innerScaleStyle]}>
                {/* Header */}
                <View style={styles.header}>
                  <Text style={[styles.headerTitle, { color: colors.text }]}>Menu</Text>
                  <TouchableOpacity
                    onPress={onClose}
                    style={styles.closeButton}
                    accessibilityLabel="Close menu"
                    accessibilityRole="button"
                  >
                    <Feather name="x" size={22} color={colors.text} />
                  </TouchableOpacity>
                </View>

                {/* Items */}
                <View style={styles.menuItems}>
                  {menuItems.map((item) => (
                    <TouchableOpacity
                      key={item.id}
                      style={{
                        marginBottom: spacing.sm,
                        borderRadius: 14,
                        shadowColor: '#000',
                        shadowOffset: { width: 0, height: 4 },
                        shadowOpacity: isDark ? 0.3 : 0.08,
                        shadowRadius: 8,
                        elevation: 2,
                        backgroundColor: 'transparent',
                      }}
                      onPress={() => handleNavigate(item.screen)}
                      accessibilityLabel={item.label}
                      activeOpacity={0.75}
                    >
                      <BlurView
                        intensity={Platform.OS === 'ios' ? 56 : 20}
                        tint={isDark ? 'dark' : 'light'}
                        style={{
                          borderRadius: 14,
                          overflow: 'hidden',
                          borderWidth: 1,
                          borderColor: isDark ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.5)',
                          backgroundColor: 'transparent',
                        }}
                      >
                        <LinearGradient
                          colors={
                            isDark
                              ? ['rgba(255,255,255,0.08)', 'rgba(255,255,255,0.04)']
                              : ['rgba(255,255,255,0.55)', 'rgba(255,255,255,0.25)']
                          }
                          start={{ x: 0, y: 0 }}
                          end={{ x: 0, y: 1 }}
                          style={{
                            flexDirection: 'row',
                            alignItems: 'center',
                            paddingVertical: spacing.md,
                            paddingHorizontal: spacing.sm,
                            minHeight: 56,
                          }}
                        >
                          <Feather name={item.icon as any} size={20} color={colors.text} style={styles.menuIcon} />
                          <Text style={[styles.menuLabel, { color: colors.text }]}>{item.label}</Text>
                          <Feather name="chevron-right" size={18} color={colors.muted ?? 'rgba(0,0,0,0.4)'} />
                        </LinearGradient>
                      </BlurView>
                    </TouchableOpacity>
                  ))}
                </View>

                {/* Footer */}
                <View style={styles.footer}>
                  <Text style={[styles.footerText, { color: colors.muted }]}>Music App v1.0
by Saw K Za</Text>
                </View>
              </Animated.View>
            </SafeAreaView>
          </LinearGradient>
        </BlurView>

        {/* Removed: glassEdge highlight that caused the white band */}
        {/* Previously here: <View pointerEvents="none" style={[styles.glassEdge, ...]} /> */}
      </Animated.View>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  container: { ...StyleSheet.absoluteFillObject },
  overlay: { ...StyleSheet.absoluteFillObject },

  drawer: {
    position: 'absolute',
    top: 0,
    overflow: 'hidden',
    borderTopRightRadius: 28,
    borderBottomRightRadius: 28,
    backgroundColor: 'transparent',
  },

  blurContainer: {
    flex: 1,
    overflow: 'hidden',
    borderTopRightRadius: 28,
    borderBottomRightRadius: 28,
  },

  gradientOverlay: { flex: 1 },
  safe: { flex: 1 },

  innerContent: {
    flex: 1,
    paddingHorizontal: spacing.md * 1.5,
    paddingTop: spacing.md * 1.5,
    paddingBottom: spacing.md,
    overflow: 'hidden',
  },

  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: spacing.md,
    paddingBottom: spacing.sm,
    marginBottom: spacing.sm,
  },
  headerTitle: {
    fontSize: 24,
    fontWeight: '900',
    letterSpacing: 0.2,
    textShadowColor: 'rgba(0,0,0,0.08)',
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 6,
  },
  closeButton: {
    padding: spacing.sm,
    borderRadius: 14,
    backgroundColor: 'rgba(255,255,255,0.03)',
  },

  menuItems: { flex: 1, paddingTop: spacing.sm },
  menuIcon: { marginRight: spacing.md, opacity: 0.95 },
  menuLabel: { fontSize: 16, fontWeight: '700', flex: 1 },

  footer: {
    paddingVertical: spacing.md,
    alignItems: 'center',
    borderTopWidth: 1,
    borderTopColor: 'rgba(255,255,255,0.03)',
    marginTop: spacing.sm,
  },
  footerText: { fontSize: 12, opacity: 0.8, letterSpacing: 0.2 },
});

export default GlassDrawer;
```

What I changed and why
- Removed the glassEdge highlight (that white “glow” line) which was bleeding into the overlay and looked like a second panel.
- Reduced elevation/shadow and adjusted shadowOffset to prevent a bright band on the overlay side.
- Moved the overlay 1px under the drawer’s right edge (left: DRAWER_WIDTH - 1) to hide any seam.

Test
- Save the file and restart Expo: npx expo start --clear
- Open/close the drawer repeatedly and navigate; the white band should be gone.
- If a tiny seam remains on some devices, increase the overlap to left: DRAWER_WIDTH - 2.

When you’re happy, commit and push:
- git add src/components/GlassDrawer.tsx
- git commit -m "fix(drawer): remove edge highlight and shadow bleed; overlap overlay by 1px"
- git push

If you still see the artifact, send a fresh screenshot and I’ll tweak the overlap/shadow values or check for any duplicate drawer mounting.

data.body:
Replaces HomeScreen's solid UI elements with glass morphism design pattern using blur effects, gradients, and floating overlays.

## Dependencies
- `expo-blur: ~14.0.1` - BlurView for iOS glass effects
- `expo-linear-gradient: ~14.0.0` - Gradient backgrounds

## Architecture

### Design System (`src/theme/designTokens.ts`)
Centralized tokens for spacing, radii, colors, and glass intensity values.

### Platform Abstraction (`src/components/GlassView.tsx`)
Handles iOS BlurView vs Android fallback with dark mode support:
```typescript
// Automatically adapts to platform and theme
<GlassView intensity={80} tint="light">
  {children}
</GlassView>
```

## New Components

**SearchBar** - Glass-effect search input with theme support  
**GlassDrawer** - Animated side navigation using `react-native-reanimated` spring animations  
**CenterMiniPill** - Horizontal scrolling filter pills with glass selection state  
**MiniPlayerOverlay** - Floating player replacing bottom bar, positioned absolutely with glass backdrop

## HomeScreen Changes

- Header: Menu icon + glass SearchBar (replaces title + action icons)
- Added drawer state management and GlassDrawer component
- Inserted CenterMiniPill below banner for content filtering (All/Playlists/Albums/Downloaded)
- Replaced static bottom player with MiniPlayerOverlay
- Removed `PLAYER_HEIGHT` constant in favor of `glass.miniPlayerHeight` from design tokens

**Before:** 374 lines, imperative player implementation  
**After:** 250 lines, declarative component composition

